function getZebraMedicalTranslation(key, lang) {
    return (zebramedicalTranslations[lang] && zebramedicalTranslations[lang][key]) ||
           (zebramedicalTranslations.en && zebramedicalTranslations.en[key]) || null;
}

function applyZebraMedicalTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.zebra-medical.") || key.startsWith("review.common."))) {
            const translation = getZebraMedicalTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} zebra-medical translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applyZebraMedicalTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyZebraMedicalTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyZebraMedicalTranslations(window.i18n?.getCurrentLanguage() || "en");
}
